do $preflight$
declare
  v_count integer;
begin
  if not exists (select 1 from public.employees where id='369d9cd5-f6ba-4e53-9428-f631f0893469'::uuid and is_active) then
    raise exception using errcode='22023',message='ACTOR_NOT_ACTIVE';
  end if;
  if exists (
    select 1 from dbf_ingest.metric_definitions where metric_code='ACTUAL_LABOR_FTE'
      and not (definition_version='ACTUAL_LABOR_FTE_173_76_V1' and value_kind='quantity'
        and display_name='実労働FTE（換算人数）' and is_active)
  ) then
    raise exception using errcode='22023',message='METRIC_DEFINITION_CONFLICT';
  end if;
  with expected as (select * from pg_temp.expected_actual_labor_fte)
  select count(*) into v_count from expected e
  join dbf_ingest.entity_mappings m on m.source_system='pos-canonical-store-actual-v1'
    and m.entity_type='store' and m.source_key=e.unit_key and m.store_id=e.store_id
    and m.status='active';
  if v_count <> 671 then
    raise exception using errcode='22023',message='STORE_MAPPING_MISMATCH';
  end if;
  with expected as (select * from pg_temp.expected_actual_labor_fte),
  op as (select * from pg_temp.expected_actual_labor_fte_operator)
  select count(*) into v_count from expected e join op
    on op.fiscal_month=e.fiscal_month and op.store_id=e.store_id
  join dbf_ingest.entity_mappings cm on cm.source_system='pos-canonical-store-actual-v1'
    and cm.entity_type='company' and cm.source_key=op.corporation_no
    and cm.company_id=op.corporation_id and cm.status='active';
  if v_count <> 666 then
    raise exception using errcode='22023',message='EFFECTIVE_OPERATOR_OR_COMPANY_MAPPING_MISMATCH';
  end if;
  with expected as (select * from pg_temp.expected_actual_labor_fte),
  op as (select * from pg_temp.expected_actual_labor_fte_operator)
  select count(*) into v_count from expected e left join op
    on op.fiscal_month=e.fiscal_month and op.store_id=e.store_id
  where op.corporation_id is null
    and not (e.unit_key='SALON:KYARAHALF'
      and e.fiscal_month between date '2023-09-01' and date '2024-01-01');
  if v_count <> 0 then
    raise exception using errcode='22023',message='UNEXPECTED_OPERATOR_GRAIN_MISSING';
  end if;
  if (select count(*) from dbf_ingest.source_files where source_system='timecard_actual_labor_fte_handoff_v1') > 1 then
    raise exception using errcode='22023',message='SOURCE_SYSTEM_DUPLICATE';
  end if;
  if exists (
    select 1 from dbf_ingest.source_files where source_system='timecard_actual_labor_fte_handoff_v1'
      and (id <> 'bc16065d-0f21-5c2a-a195-1713a527f7ed'::uuid or sha256 <> lower('ED36524E26E78A5758B6A7CF82FF772BC546595197AED57DEE7ED1863084FF01')
        or byte_size <> 316433)
  ) then
    raise exception using errcode='22023',message='SOURCE_IDENTITY_CONFLICT';
  end if;
  if not exists (
    select 1 from dbf_ingest.source_files where source_system='timecard_actual_labor_fte_handoff_v1'
  ) and exists (
    select 1 from public.dbf_store_monthly_metric_facts
    where metric_code='ACTUAL_LABOR_FTE' and is_active
  ) then
    raise exception using errcode='23505',message='ACTIVE_FACTS_ALREADY_EXIST';
  end if;
end
$preflight$;

do $definition$
begin
  if not exists (
    select 1 from dbf_ingest.metric_definitions
    where metric_code='ACTUAL_LABOR_FTE' and definition_version='ACTUAL_LABOR_FTE_173_76_V1'
      and value_kind='quantity' and display_name='実労働FTE（換算人数）' and is_active
  ) then
    execute 'alter table dbf_ingest.metric_definitions drop constraint metric_definitions_metric_code_check';
    execute $ddl$alter table dbf_ingest.metric_definitions
      add constraint metric_definitions_metric_code_check
      check (metric_code = any (array['TOTAL_SALES'::text,'TECHNICAL_SALES'::text,'RETAIL_SALES'::text,'MID_SALES'::text,'EC_ALLOCATED_SALES'::text,'TOTAL_CUSTOMERS'::text,'NEW_CUSTOMERS'::text,'EXISTING_CUSTOMERS'::text,'TOTAL_UNIT_PRICE'::text,'TECHNICAL_UNIT_PRICE'::text,'TOTAL_REPEAT_RATE'::text,'NEW_REPEAT_RATE'::text,'SECOND_REPEAT_RATE'::text,'THIRD_REPEAT_RATE'::text,'FIXED_REPEAT_RATE'::text,'TOTAL_PRODUCTIVITY'::text,'TECHNICAL_PRODUCTIVITY'::text,'RETAIL_PURCHASE_RATE'::text,'RETAIL_PURCHASE_CUSTOMER_VISITS'::text,'ACTUAL_LABOR_FTE'::text,'OPERATING_PROFIT'::text]))$ddl$;
    insert into dbf_ingest.metric_definitions
      (metric_code,definition_version,value_kind,display_name,description,is_active)
    values ('ACTUAL_LABOR_FTE','ACTUAL_LABOR_FTE_173_76_V1','quantity','実労働FTE（換算人数）',
      'タイムカード社員月総実労働時間を同月の正式な店舗配置FTE比率で配賦し、173.76時間を1.0FTEとして算出。実際の打刻店舗・応援先を示さず、実勤怠なしはNULL。',
      true);
  end if;
end
$definition$;

do $load$
declare
  v_actor constant uuid := '369d9cd5-f6ba-4e53-9428-f631f0893469'::uuid;
  v_source constant uuid := 'bc16065d-0f21-5c2a-a195-1713a527f7ed'::uuid;
  v_batch record;
  v_result jsonb;
  v_count integer;
begin
  if exists (select 1 from dbf_ingest.source_files where id=v_source) then
    with expected as (select * from pg_temp.expected_actual_labor_fte),
    op as (select * from pg_temp.expected_actual_labor_fte_operator)
    select count(*) into v_count from expected e join op
      on op.fiscal_month=e.fiscal_month and op.store_id=e.store_id
    join public.dbf_store_monthly_metric_facts f
      on f.fiscal_month=e.fiscal_month and f.company_id=op.corporation_id
      and f.store_id=e.store_id and f.metric_code='ACTUAL_LABOR_FTE'
      and f.quantity=round(e.value_quantity,4) and f.definition_version='ACTUAL_LABOR_FTE_173_76_V1'
      and f.source_file_id=v_source and f.status='confirmed' and f.is_active;
    if v_count <> 666
       or (select count(*) from dbf_ingest.import_batches
           where source_file_id=v_source and fact_kind='store_operating_result'
             and source_type='timecard_actual_labor_fte_173_76_v1' and status='promoted') <> 36
       or (select count(*) from dbf_ingest.import_batches
           where source_file_id=v_source and fact_kind='store_operating_result'
             and source_type='timecard_actual_labor_fte_operator_quarantine_v1' and status='mapping_required')
          <> 5
       or (select count(*) from dbf_ingest.raw_rows r join dbf_ingest.import_batches b
           on b.id=r.batch_id where b.source_file_id=v_source) <> 671
       or (select count(*) from dbf_ingest.staging_rows s join dbf_ingest.import_batches b
           on b.id=s.batch_id where b.source_file_id=v_source) <> 671 then
      raise exception using errcode='22023',message='EXISTING_PACKAGE_READBACK_MISMATCH';
    end if;
    return;
  end if;

  insert into dbf_ingest.source_files
    (id,sha256,byte_size,original_file_name,media_type,source_system,
     received_by_employee_id,received_via)
  values (v_source,lower('ED36524E26E78A5758B6A7CF82FF772BC546595197AED57DEE7ED1863084FF01'),316433,
    'actual-labor-fte-canonical-20260924.json','application/json',
    'timecard_actual_labor_fte_handoff_v1',v_actor,'nov_hub_secure_session');

  for v_batch in
    select * from jsonb_to_recordset('[{"batch_id":"d6347a7d-942e-5860-af35-bb00f44c3e5f","fiscal_month":"2023-09"},{"batch_id":"85429b93-afb2-5392-9713-1c0fa061abbc","fiscal_month":"2023-10"},{"batch_id":"ecf479c3-1c75-58cb-962e-a442879c1ff4","fiscal_month":"2023-11"},{"batch_id":"1689b50b-81c7-5140-a837-e5e22861873e","fiscal_month":"2023-12"},{"batch_id":"4b19d946-50da-549d-8eab-7a80328a5046","fiscal_month":"2024-01"},{"batch_id":"b963fc7e-adc2-5ca6-ba3c-496407d38531","fiscal_month":"2024-02"},{"batch_id":"bb60ec47-55e0-518f-bdb4-dbbc64f3df49","fiscal_month":"2024-03"},{"batch_id":"0561f37e-a4ad-59d2-87f3-08720a31ddd5","fiscal_month":"2024-04"},{"batch_id":"d270c776-3c50-5991-90a3-48b81d2bc3fa","fiscal_month":"2024-05"},{"batch_id":"466b5600-7795-5756-8e1d-475041374f0f","fiscal_month":"2024-06"},{"batch_id":"a0983e0c-0a41-55f4-879d-835a358ce055","fiscal_month":"2024-07"},{"batch_id":"f8d1121e-3141-5a8e-9011-4adfbe0cd3c3","fiscal_month":"2024-08"},{"batch_id":"e3920f9c-8a54-5405-afb4-92bae0961d84","fiscal_month":"2024-09"},{"batch_id":"161033d2-54a8-5d20-97fc-c7a396bc24bf","fiscal_month":"2024-10"},{"batch_id":"4969922e-81dd-512c-975e-d81063c4c357","fiscal_month":"2024-11"},{"batch_id":"f98ebcba-90b8-54c5-9fb9-8d68758f6619","fiscal_month":"2024-12"},{"batch_id":"ae2029f6-6522-5b84-b3de-33378f198097","fiscal_month":"2025-01"},{"batch_id":"029525b6-3b5f-57cc-97bc-2e3f7b62e34b","fiscal_month":"2025-02"},{"batch_id":"fe2d4770-de62-5c29-8158-dbc27aa37b38","fiscal_month":"2025-03"},{"batch_id":"bd0ba604-9955-511c-a864-6d3cd56b1dde","fiscal_month":"2025-04"},{"batch_id":"d163a5f4-2da2-516f-915e-5fe96ef5d92a","fiscal_month":"2025-05"},{"batch_id":"c610efe3-16cf-533d-a919-6fb3ee053083","fiscal_month":"2025-06"},{"batch_id":"de94956a-e989-5430-ab27-99d592f59b2a","fiscal_month":"2025-07"},{"batch_id":"fb7f8554-0ac4-5bf9-944b-4409bdd50e21","fiscal_month":"2025-08"},{"batch_id":"944c589d-6e84-5c08-89c1-f073824dbe18","fiscal_month":"2025-09"},{"batch_id":"e70afc55-390d-5075-8a01-111ff98ba465","fiscal_month":"2025-10"},{"batch_id":"5c964f39-67c9-57d5-8021-81216e7912f2","fiscal_month":"2025-11"},{"batch_id":"43cfe1f3-3832-537f-a5fb-303762a1f32d","fiscal_month":"2025-12"},{"batch_id":"a611f6b5-418a-551b-a4fd-d27911b28cc0","fiscal_month":"2026-01"},{"batch_id":"029d7896-3ab2-52c0-962c-9099c1a130a4","fiscal_month":"2026-02"},{"batch_id":"51d52a0e-fa7b-5742-9948-cc474238f3bc","fiscal_month":"2026-03"},{"batch_id":"ba94a307-9381-5f55-85e5-3c9b29b15451","fiscal_month":"2026-04"},{"batch_id":"ec511097-86b1-5328-a704-f853cb7361d9","fiscal_month":"2026-05"},{"batch_id":"afc07fde-ebfd-5bd4-a1f2-0476d889d303","fiscal_month":"2026-06"},{"batch_id":"87ce50b2-8f2e-5583-834c-120701f7ad98","fiscal_month":"2026-07"},{"batch_id":"2c8aaa86-8f11-5a1d-807c-f688318bcae3","fiscal_month":"2026-08"}]'::jsonb)
      as b(fiscal_month date,batch_id uuid)
    order by fiscal_month
  loop
    insert into dbf_ingest.import_batches
      (id,source_file_id,fact_kind,fiscal_month,source_type,status,revision,
       created_by_employee_id)
    values (v_batch.batch_id,v_source,'store_operating_result',
      v_batch.fiscal_month,'timecard_actual_labor_fte_173_76_v1','owner_review',1,v_actor);

    with expected as (
      select e.*,row_number() over(order by e.unit_key)::integer source_row_number
      from pg_temp.expected_actual_labor_fte e where e.fiscal_month=v_batch.fiscal_month
        and not (e.unit_key='SALON:KYARAHALF'
          and e.fiscal_month between date '2023-09-01' and date '2024-01-01')
    )
    insert into dbf_ingest.raw_rows
      (batch_id,source_row_number,payload,payload_sha256)
    select v_batch.batch_id,source_row_number,
      jsonb_build_object(
        'fiscalMonth',to_char(fiscal_month,'YYYY-MM'),
        'unitKey',unit_key,'storeName',store_name,'storeId',store_id,
        'metricCode','ACTUAL_LABOR_FTE','definitionVersion','ACTUAL_LABOR_FTE_173_76_V1',
        'valueQuantityExact',value_quantity::text,
        'allocatedActualWorkMinutesExact',allocated_actual_work_minutes::text,
        'allocatedActualWorkHoursExact',allocated_actual_work_hours::text,
        'referenceHoursExact',reference_hours::text,
        'sourceWorkbookSha256',source_workbook_sha256,
        'fingerprintSha256',fingerprint_sha256),
      fingerprint_sha256
    from expected order by source_row_number;

    with expected as (
      select e.*,row_number() over(order by e.unit_key)::integer source_row_number
      from pg_temp.expected_actual_labor_fte e where e.fiscal_month=v_batch.fiscal_month
        and not (e.unit_key='SALON:KYARAHALF'
          and e.fiscal_month between date '2023-09-01' and date '2024-01-01')
    ),
    op as (
      select * from pg_temp.expected_actual_labor_fte_operator
      where fiscal_month=v_batch.fiscal_month
    )
    insert into dbf_ingest.staging_rows(
      batch_id,raw_row_id,company_mapping_id,store_mapping_id,company_id,store_id,
      metric_code,amount,quantity,rate,source_row_category,mapping_status,
      validation_status,normalized_payload
    )
    select v_batch.batch_id,r.id,cm.id,sm.id,op.corporation_id,e.store_id,
      'ACTUAL_LABOR_FTE',null,round(e.value_quantity,4),null,'detail','resolved','valid',
      jsonb_build_object(
        'definitionVersion','ACTUAL_LABOR_FTE_173_76_V1','confirmationStatus','confirmed',
        'valueQuantityExact',e.value_quantity::text,
        'allocatedActualWorkMinutesExact',e.allocated_actual_work_minutes::text,
        'allocatedActualWorkHoursExact',e.allocated_actual_work_hours::text,
        'referenceHoursExact',e.reference_hours::text,
        'allocationMethod','SAME_MONTH_OFFICIAL_FTE_PLACEMENT_RATIO',
        'actualPunchStore',false,'shiftBackfill',false,
        'sourceWorkbookSha256',e.source_workbook_sha256,
        'fingerprintSha256',e.fingerprint_sha256)
    from expected e
    join dbf_ingest.raw_rows r on r.batch_id=v_batch.batch_id
      and r.source_row_number=e.source_row_number
    join op on op.fiscal_month=e.fiscal_month and op.store_id=e.store_id
    join dbf_ingest.entity_mappings sm on sm.source_system='pos-canonical-store-actual-v1'
      and sm.entity_type='store' and sm.source_key=e.unit_key
      and sm.store_id=e.store_id and sm.status='active'
    join dbf_ingest.entity_mappings cm on cm.source_system='pos-canonical-store-actual-v1'
      and cm.entity_type='company' and cm.source_key=op.corporation_no
      and cm.company_id=op.corporation_id and cm.status='active';

    if (select count(*) from dbf_ingest.staging_rows
        where batch_id=v_batch.batch_id and mapping_status='resolved'
          and validation_status='valid') <> (select count(*) from dbf_ingest.raw_rows
        where batch_id=v_batch.batch_id) then
      raise exception using errcode='22023',message='MONTH_STAGE_COUNT_MISMATCH';
    end if;

    insert into dbf_ingest.import_events(
      batch_id,event_type,from_status,to_status,actor_employee_id,summary
    ) values
      (v_batch.batch_id,'SOURCE_PARSED','received','parsed',v_actor,
       jsonb_build_object('rowCount',(select count(*) from dbf_ingest.raw_rows
         where batch_id=v_batch.batch_id),'sourceSha256','ED36524E26E78A5758B6A7CF82FF772BC546595197AED57DEE7ED1863084FF01')),
      (v_batch.batch_id,'VALIDATION_COMPLETED','parsed','owner_review',v_actor,
       jsonb_build_object('errorCount',0,'warningCount',0));

    v_result := public.dbf_import_approve_v1(v_actor,v_batch.batch_id);
    if v_result->>'status' <> 'approved' then
      raise exception using errcode='22023',message='APPROVAL_RESULT_MISMATCH';
    end if;
    v_result := public.dbf_import_promote_v1(v_actor,v_batch.batch_id);
    if v_result->>'status' <> 'promoted' then
      raise exception using errcode='22023',message='PROMOTION_RESULT_MISMATCH';
    end if;
  end loop;

  for v_batch in
    select * from jsonb_to_recordset('[{"batch_id":"e2be0763-424e-53b3-b335-1b3530e92e3c","fiscal_month":"2023-09"},{"batch_id":"b407da80-39cf-5245-9441-2a146fe26dfc","fiscal_month":"2023-10"},{"batch_id":"17c62545-f6c4-5cab-9ba9-a23125ad3d0b","fiscal_month":"2023-11"},{"batch_id":"b766f2d7-941b-529f-9501-36925c8a01ea","fiscal_month":"2023-12"},{"batch_id":"8cbbe8ab-bb80-51b5-a1f7-e13ec49af7c1","fiscal_month":"2024-01"}]'::jsonb)
      as b(fiscal_month date,batch_id uuid)
    order by fiscal_month
  loop
    insert into dbf_ingest.import_batches
      (id,source_file_id,fact_kind,fiscal_month,source_type,status,revision,
       created_by_employee_id)
    values (v_batch.batch_id,v_source,'store_operating_result',
      v_batch.fiscal_month,'timecard_actual_labor_fte_operator_quarantine_v1','mapping_required',1,v_actor);

    with expected as (
      select e.*,1::integer source_row_number
      from pg_temp.expected_actual_labor_fte e
      where e.fiscal_month=v_batch.fiscal_month and e.unit_key='SALON:KYARAHALF'
    )
    insert into dbf_ingest.raw_rows
      (batch_id,source_row_number,payload,payload_sha256)
    select v_batch.batch_id,source_row_number,
      jsonb_build_object(
        'fiscalMonth',to_char(fiscal_month,'YYYY-MM'),
        'unitKey',unit_key,'storeName',store_name,'storeId',store_id,
        'metricCode','ACTUAL_LABOR_FTE','definitionVersion','ACTUAL_LABOR_FTE_173_76_V1',
        'valueQuantityExact',value_quantity::text,
        'allocatedActualWorkMinutesExact',allocated_actual_work_minutes::text,
        'allocatedActualWorkHoursExact',allocated_actual_work_hours::text,
        'referenceHoursExact',reference_hours::text,
        'sourceWorkbookSha256',source_workbook_sha256,
        'fingerprintSha256',fingerprint_sha256),
      fingerprint_sha256
    from expected;

    with expected as (
      select e.*,1::integer source_row_number
      from pg_temp.expected_actual_labor_fte e
      where e.fiscal_month=v_batch.fiscal_month and e.unit_key='SALON:KYARAHALF'
    )
    insert into dbf_ingest.staging_rows(
      batch_id,raw_row_id,company_mapping_id,store_mapping_id,company_id,store_id,
      metric_code,amount,quantity,rate,source_row_category,mapping_status,
      validation_status,normalized_payload
    )
    select v_batch.batch_id,r.id,null,sm.id,null,e.store_id,
      'ACTUAL_LABOR_FTE',null,round(e.value_quantity,4),null,'detail',
      'quarantined','quarantined',
      jsonb_build_object(
        'definitionVersion','ACTUAL_LABOR_FTE_173_76_V1',
        'valueQuantityExact',e.value_quantity::text,
        'allocatedActualWorkMinutesExact',e.allocated_actual_work_minutes::text,
        'allocatedActualWorkHoursExact',e.allocated_actual_work_hours::text,
        'referenceHoursExact',e.reference_hours::text,
        'allocationMethod','SAME_MONTH_OFFICIAL_FTE_PLACEMENT_RATIO',
        'actualPunchStore',false,'shiftBackfill',false,
        'reasonCode','MISSING_EFFECTIVE_OPERATOR',
        'sourceWorkbookSha256',e.source_workbook_sha256,
        'fingerprintSha256',e.fingerprint_sha256)
    from expected e
    join dbf_ingest.raw_rows r on r.batch_id=v_batch.batch_id
      and r.source_row_number=e.source_row_number
    join dbf_ingest.entity_mappings sm on sm.source_system='pos-canonical-store-actual-v1'
      and sm.entity_type='store' and sm.source_key=e.unit_key
      and sm.store_id=e.store_id and sm.status='active';

    if (select count(*) from dbf_ingest.staging_rows
        where batch_id=v_batch.batch_id and mapping_status='quarantined'
          and validation_status='quarantined'
          and normalized_payload->>'reasonCode'='MISSING_EFFECTIVE_OPERATOR') <> 1 then
      raise exception using errcode='22023',message='QUARANTINE_STAGE_COUNT_MISMATCH';
    end if;

    insert into dbf_ingest.import_events(
      batch_id,event_type,from_status,to_status,actor_employee_id,reason_code,summary
    ) values
      (v_batch.batch_id,'SOURCE_PARSED','received','parsed',v_actor,null,
       jsonb_build_object('rowCount',1,'sourceSha256','ED36524E26E78A5758B6A7CF82FF772BC546595197AED57DEE7ED1863084FF01')),
      (v_batch.batch_id,'MAPPING_REQUIRED','parsed','mapping_required',v_actor,
       'MISSING_EFFECTIVE_OPERATOR',
       jsonb_build_object('rowCount',1,'canonicalPromotion',false));
  end loop;

  with expected as (select * from pg_temp.expected_actual_labor_fte),
  op as (select * from pg_temp.expected_actual_labor_fte_operator)
  select count(*) into v_count from expected e join op
    on op.fiscal_month=e.fiscal_month and op.store_id=e.store_id
  join public.dbf_store_monthly_metric_facts f
    on f.fiscal_month=e.fiscal_month and f.company_id=op.corporation_id
    and f.store_id=e.store_id and f.metric_code='ACTUAL_LABOR_FTE'
    and f.quantity=round(e.value_quantity,4) and f.definition_version='ACTUAL_LABOR_FTE_173_76_V1'
    and f.source_file_id=v_source and f.status='confirmed' and f.is_active;
  if v_count <> 666
     or (select count(*) from dbf_ingest.import_batches
         where source_file_id=v_source and fact_kind='store_operating_result'
           and source_type='timecard_actual_labor_fte_173_76_v1' and status='promoted') <> 36
     or (select count(*) from dbf_ingest.import_batches
         where source_file_id=v_source and fact_kind='store_operating_result'
           and source_type='timecard_actual_labor_fte_operator_quarantine_v1' and status='mapping_required')
        <> 5
     or (select count(*) from dbf_ingest.raw_rows r join dbf_ingest.import_batches b
         on b.id=r.batch_id where b.source_file_id=v_source) <> 671
     or (select count(*) from dbf_ingest.staging_rows s join dbf_ingest.import_batches b
         on b.id=s.batch_id where b.source_file_id=v_source) <> 671
     or (select count(*) from dbf_ingest.import_events ev join dbf_ingest.import_batches b
         on b.id=ev.batch_id where b.source_file_id=v_source)
        <> 154
     or (select count(*) from dbf_ingest.staging_rows s
         join dbf_ingest.import_batches b on b.id=s.batch_id
         where b.source_file_id=v_source
           and b.source_type='timecard_actual_labor_fte_operator_quarantine_v1'
           and s.mapping_status='quarantined'
           and s.validation_status='quarantined'
           and s.normalized_payload->>'reasonCode'='MISSING_EFFECTIVE_OPERATOR')
        <> 5
     or exists (
       select 1 from public.dbf_store_monthly_metric_facts f
       where f.metric_code='ACTUAL_LABOR_FTE' and f.is_active
         and f.source_file_id <> v_source
     ) then
    raise exception using errcode='22023',message='FINAL_READBACK_MISMATCH';
  end if;
end
$load$;

commit;
